impl<T: gx::Real, O: gx::Orientation> Vector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[2] * x[2];
        let t2 = x[3] * x[3];
        let t4 = x[1].mul_add(x[1], t1);
        let t5 = (-x[4]).mul_add(x[4], t2);
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (24 mul, 12 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Vector<(), T, O> {
        let x = self.c;
        let t0 = x[1] * x[1];
        let t1 = x[2] * x[2];
        let t2 = x[3] * x[3];
        let t3 = x[4] * x[4];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t0.mul_add(t1, t6);
        let t18 = t1.mul_add(t2, t17);
        let t19 = t0.mul_add(t3, t10);
        let t20 = t2.mul_add(t3, t19);
        let t21 = t18 - t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t29 = t0.mul_add(t24, t26);
        let t30 = (-t3).mul_add(t24, t27);
        let t31 = t29 + t30;
        let t32 = x[0] * t31;
        let t33 = x[1] * t31;
        let t34 = x[2] * t31;
        let t35 = x[3] * t31;
        let t36 = x[4] * t31;
        Vector::from_coeffs([t32, t33, t34, t35, t36])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 5` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Vector<(), T, O>> {
        let x = self.c;
        let t0 = x[1] * x[1];
        let t1 = x[2] * x[2];
        let t2 = x[3] * x[3];
        let t3 = x[4] * x[4];
        let t7 = t0 * t2;
        let t9 = t1 * t1;
        let t11 = t1 * t3;
        let t14 = t3 * t3;
        let t15 = t0 + t1;
        let t16 = t2 + t15;
        let t17 = x[0].mul_add(x[0], t3);
        let t18 = t16 + t17;
        let t19 = t16 - t3;
        let t20 = t0.mul_add(t0, t9);
        let t21 = t2.mul_add(t2, t14);
        let t22 = t20 + t21;
        let t23 = t0.mul_add(t1, t7);
        let t24 = t1.mul_add(t2, t23);
        let t25 = t0.mul_add(t3, t11);
        let t26 = t2.mul_add(t3, t25);
        let t27 = t24 - t26;
        let t29 = t27.mul_add(T::from_i64(2), t22);
        let (size, d) = (t18, t29);
        let parts = t19 * t19;
        let tol = T::from_i64(5) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[2] * x[2];
        let p2 = x[3] * x[3];
        let p4 = x[1].mul_add(x[1], p1);
        let p5 = (-x[4]).mul_add(x[4], p2);
        let p6 = p4 + p5;
        let s0 = (p6).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1, t2, t3, t4]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Vector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[2] * x[2];
        let t2 = x[3] * x[3];
        let t4 = x[1].mul_add(x[1], t1);
        let t5 = (-x[4]).mul_add(x[4], t2);
        let t6 = t4 + t5;
        let t8 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t9 = x[0] * t8;
        let t10 = x[1] * t8;
        let t11 = x[2] * t8;
        let t12 = x[3] * t8;
        let t13 = x[4] * t8;
        let t14 = t9 * T::from_ratio(3, 2);
        let t15 = t10 * T::from_ratio(3, 2);
        let t16 = t11 * T::from_ratio(3, 2);
        let t17 = t12 * T::from_ratio(3, 2);
        let t18 = t13 * T::from_ratio(3, 2);
        Vector::from_coeffs([t14, t15, t16, t17, t18])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

