impl<T: gx::Real, O: gx::Orientation> Trivector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[6] * x[6];
        let t3 = x[9] * x[9];
        let t4 = (-x[7]).mul_add(x[7], t0);
        let t5 = x[8].mul_add(x[8], t3);
        let t6 = t4 - t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (68 mul, 43 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Trivector<(), T, O> {
        let x = self.c;
        let t0 = x[6] * x[6];
        let t1 = x[7] * x[7];
        let t2 = x[8] * x[8];
        let t3 = x[9] * x[9];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t1.mul_add(t2, t10);
        let t18 = t2.mul_add(t3, t17);
        let t19 = t0.mul_add(t1, t6);
        let t20 = t0.mul_add(t3, t19);
        let t21 = t18 - t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 - t26;
        let t30 = t27 + t28;
        let t31 = t29 - t30;
        let t32 = t25 + t26;
        let t33 = t27 - t28;
        let t34 = t25 + t27;
        let t35 = t28 - t26;
        let t36 = t34 + t35;
        let t37 = t32 - t33;
        let t38 = t32 + t33;
        let t39 = x[6] * t24;
        let t40 = x[7] * t24;
        let t41 = x[7] * t39;
        let t42 = x[8] * x[9];
        let t43 = x[8] * t39;
        let t44 = x[8] * t40;
        let t45 = x[9] * t39;
        let t46 = x[9] * t40;
        let t47 = t24 * t42;
        let t50 = x[2] * t46;
        let t51 = x[4] * t45;
        let t55 = x[2] * t47;
        let t57 = x[5] * t41;
        let t59 = x[1] * t47;
        let t61 = x[3] * t43;
        let t63 = x[1] * t45;
        let t67 = x[5] * t46;
        let t69 = x[2] * t41;
        let t72 = x[5] * t47;
        let t73 = x[0] * t43;
        let t76 = x[4] * t47;
        let t78 = x[6] * t31;
        let t79 = x[7] * t31;
        let t80 = x[8] * t31;
        let t81 = x[9] * t31;
        let t82 = x[1].mul_add(t44, t50);
        let t83 = (-x[5]).mul_add(t43, t51);
        let t84 = t82 + t83;
        let t85 = t84 * T::from_i64(2);
        let t86 = (-x[0]).mul_add(t36, t85);
        let t87 = x[0].mul_add(t44, t55);
        let t88 = (-x[3]).mul_add(t45, t57);
        let t89 = t87 + t88;
        let t90 = t89 * T::from_i64(2);
        let t91 = (-x[1]).mul_add(t37, t90);
        let t92 = x[0].mul_add(t46, t59);
        let t93 = (-x[4]).mul_add(t41, t61);
        let t94 = t92 + t93;
        let t95 = t94 * T::from_i64(2);
        let t96 = (-x[2]).mul_add(t38, t95);
        let t97 = (-x[2]).mul_add(t43, t63);
        let t98 = x[4].mul_add(t44, t67);
        let t99 = t97 - t98;
        let t100 = t99 * T::from_i64(2);
        let t101 = x[3].mul_add(t36, t100);
        let t102 = (-x[0]).mul_add(t45, t69);
        let t103 = x[3].mul_add(t44, t72);
        let t104 = t102 - t103;
        let t105 = t104 * T::from_i64(2);
        let t106 = x[4].mul_add(t37, t105);
        let t107 = (-x[1]).mul_add(t41, t73);
        let t108 = x[3].mul_add(t46, t76);
        let t109 = t107 - t108;
        let t110 = t109 * T::from_i64(2);
        let t111 = x[5].mul_add(t38, t110);
        let t112 = -t78;
        let t113 = -t79;
        let t114 = -t80;
        let t115 = -t81;
        Trivector::from_coeffs([t86, t91, t96, t101, t106, t111, t112, t113, t114, t115])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 10` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Trivector<(), T, O>> {
        let x = self.c;
        let t0 = x[6] * x[6];
        let t1 = x[7] * x[7];
        let t2 = x[8] * x[8];
        let t3 = x[9] * x[9];
        let t6 = x[2] * x[2];
        let t8 = x[4] * x[4];
        let t11 = x[4] * x[8];
        let t15 = x[5] * x[6];
        let t16 = x[0] * x[9];
        let t21 = x[3] * x[6];
        let t24 = t0 * t2;
        let t26 = t1 * t1;
        let t28 = t1 * t3;
        let t31 = t3 * t3;
        let t32 = t1 + t2;
        let t33 = t3 + t32;
        let t34 = x[0].mul_add(x[0], t0);
        let t35 = x[1].mul_add(x[1], t6);
        let t36 = t34 + t35;
        let t37 = x[3].mul_add(x[3], t8);
        let t38 = x[5].mul_add(x[5], t33);
        let t39 = t37 + t38;
        let t40 = t36 + t39;
        let t41 = t0 - t33;
        let t42 = x[3].mul_add(x[7], t11);
        let t43 = x[5].mul_add(x[9], t42);
        let t44 = t43 * T::from_i64(2);
        let t45 = x[0].mul_add(x[8], t15);
        let t46 = (-x[1]).mul_add(x[7], t45);
        let t47 = t46 * T::from_i64(2);
        let t48 = (-x[2]).mul_add(x[7], t16);
        let t49 = (-x[4]).mul_add(x[6], t48);
        let t50 = t49 * T::from_i64(2);
        let t51 = x[1].mul_add(x[9], t21);
        let t52 = (-x[2]).mul_add(x[8], t51);
        let t53 = t52 * T::from_i64(2);
        let t54 = t0.mul_add(t0, t26);
        let t55 = t2.mul_add(t2, t31);
        let t56 = t54 + t55;
        let t57 = t1.mul_add(t2, t28);
        let t58 = t2.mul_add(t3, t57);
        let t59 = t0.mul_add(t1, t24);
        let t60 = t0.mul_add(t3, t59);
        let t61 = t58 - t60;
        let t63 = t61.mul_add(T::from_i64(2), t56);
        let (size, d) = (t40, t63);
        let parts = t41 * t41 + t44 * t44 + t47 * t47 + t50 * t50 + t53 * t53;
        let tol = T::from_i64(10) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x` with `x ~x = a + X` a scalar and a 4-vector
    /// whose square is a scalar, so that `x ~x = 1` (`â1` when `a` is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[6] * x[6];
        let p3 = x[9] * x[9];
        let p4 = (-x[7]).mul_add(x[7], p0);
        let p5 = x[8].mul_add(x[8], p3);
        let p6 = p4 - p5;
        let [s0, s1] = gx::__private::study::rsqrt_q(p6, T::from_i64(0));
        let t0 = x[0] * x[8];
        let t2 = x[1] * x[7];
        let t4 = x[5] * x[6];
        let t5 = s1 * t4;
        let t6 = s1.mul_add(t0, t5);
        let t7 = (-s1).mul_add(t2, t6);
        let t8 = x[0] * x[9];
        let t9 = s1 * t8;
        let t10 = x[2] * x[7];
        let t12 = x[4] * x[6];
        let t14 = (-s1).mul_add(t10, t9);
        let t15 = (-s1).mul_add(t12, t14);
        let t16 = x[1] * x[9];
        let t18 = x[2] * x[8];
        let t20 = x[3] * x[6];
        let t21 = s1 * t20;
        let t22 = s1.mul_add(t16, t21);
        let t23 = (-s1).mul_add(t18, t22);
        let t24 = x[3] * x[7];
        let t26 = x[4] * x[8];
        let t27 = s1 * t26;
        let t28 = x[5] * x[9];
        let t30 = s1.mul_add(t24, t27);
        let t31 = s1.mul_add(t28, t30);
        let t32 = x[0] * s0;
        let t34 = x[9] * t15;
        let t36 = x[7] * t7;
        let t40 = x[8] * t23;
        let t42 = x[6] * t23;
        let t44 = x[4] * s0;
        let t46 = x[8] * t31;
        let t48 = x[6] * t7;
        let t50 = x[6] * s0;
        let t51 = x[7] * s0;
        let t52 = x[8] * s0;
        let t53 = x[9] * s0;
        let t54 = x[8].mul_add(t7, t34);
        let t56 = (-t54).mul_add(T::from_i64(2), t32);
        let t57 = (-x[9]).mul_add(t23, t36);
        let t58 = t57 * T::from_i64(2);
        let t59 = x[1].mul_add(s0, t58);
        let t60 = x[7].mul_add(t15, t40);
        let t61 = t60 * T::from_i64(2);
        let t62 = x[2].mul_add(s0, t61);
        let t63 = (-x[7]).mul_add(t31, t42);
        let t64 = t63 * T::from_i64(2);
        let t65 = x[3].mul_add(s0, t64);
        let t66 = x[6].mul_add(t15, t46);
        let t68 = (-t66).mul_add(T::from_i64(2), t44);
        let t69 = (-x[9]).mul_add(t31, t48);
        let t70 = t69 * T::from_i64(2);
        let t71 = x[5].mul_add(s0, t70);
        gx::Unit::new_unchecked(Trivector::from_coeffs([t56, t59, t62, t65, t68, t71, t50, t51, t52, t53]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Trivector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[6] * x[6];
        let t1 = x[7] * x[7];
        let t2 = x[8] * x[8];
        let t3 = x[9] * x[9];
        let t4 = t0 - t1;
        let t5 = t2 + t3;
        let t6 = t4 - t5;
        let t7 = T::from_i64(1) - t0;
        let t9 = t1.mul_add(T::from_ratio(1, 3), t7);
        let t10 = t1 + T::from_i64(1);
        let t12 = (-t0).mul_add(T::from_ratio(1, 3), t10);
        let t14 = t3.mul_add(T::from_ratio(1, 3), t2);
        let t16 = t3.mul_add(T::from_i64(3), t2);
        let t18 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t19 = x[6] * x[7];
        let t20 = x[6] * x[8];
        let t21 = x[6] * x[9];
        let t22 = x[7] * x[8];
        let t23 = x[7] * x[9];
        let t24 = x[8] * x[9];
        let t25 = x[0] * t4;
        let t29 = x[4] * t21;
        let t30 = x[5] * t20;
        let t32 = x[1] * t12;
        let t33 = x[1] * t16;
        let t35 = x[3] * t21;
        let t36 = x[5] * t19;
        let t40 = x[2] * t14;
        let t41 = x[3] * t20;
        let t42 = x[4] * t19;
        let t46 = x[3] * t5;
        let t47 = x[4] * t22;
        let t48 = x[5] * t23;
        let t51 = x[3] * t22;
        let t53 = x[4] * t14;
        let t54 = x[5] * t24;
        let t57 = x[3] * t23;
        let t58 = x[4] * t24;
        let t59 = x[5] * t9;
        let t60 = x[5] * t16;
        let t61 = x[6] * t18;
        let t62 = x[7] * t18;
        let t63 = x[8] * t18;
        let t64 = x[9] * t18;
        let t65 = (-x[1]).mul_add(t22, t30);
        let t66 = x[2].mul_add(t23, t29);
        let t67 = t65 - t66;
        let t69 = x[0].mul_add(t5, x[0]);
        let t71 = t69.mul_add(T::from_ratio(3, 2), t67);
        let t72 = (-t25).mul_add(T::from_ratio(1, 2), t71);
        let t73 = (-x[0]).mul_add(t22, t35);
        let t74 = x[2].mul_add(t24, t36);
        let t75 = t73 - t74;
        let t78 = t33.mul_add(T::from_ratio(1, 2), t75);
        let t79 = t32.mul_add(T::from_ratio(3, 2), t78);
        let t80 = (-x[0]).mul_add(t23, t42);
        let t81 = x[1].mul_add(t24, t41);
        let t82 = t80 - t81;
        let t83 = x[2].mul_add(t12, t40);
        let t85 = t83.mul_add(T::from_ratio(3, 2), t82);
        let t86 = x[2].mul_add(t20, t47);
        let t87 = (-x[1]).mul_add(t21, t48);
        let t88 = t86 + t87;
        let t90 = (-x[3]).mul_add(t4, x[3]);
        let t92 = t46.mul_add(T::from_ratio(1, 2), t88);
        let t93 = t90.mul_add(T::from_ratio(3, 2), t92);
        let t94 = x[0].mul_add(t21, t51);
        let t95 = (-x[2]).mul_add(t19, t54);
        let t96 = t94 + t95;
        let t97 = x[4].mul_add(t9, t53);
        let t99 = t97.mul_add(T::from_ratio(3, 2), t96);
        let t100 = x[1].mul_add(t19, t57);
        let t101 = (-x[0]).mul_add(t20, t58);
        let t102 = t100 + t101;
        let t105 = t60.mul_add(T::from_ratio(1, 2), t102);
        let t106 = t59.mul_add(T::from_ratio(3, 2), t105);
        let t107 = t61 * T::from_ratio(3, 2);
        let t108 = t62 * T::from_ratio(3, 2);
        let t109 = t63 * T::from_ratio(3, 2);
        let t110 = t64 * T::from_ratio(3, 2);
        Trivector::from_coeffs([t72, t79, t85, t93, t99, t106, t107, t108, t109, t110])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

