impl<T: gx::Real, O: gx::Orientation> Quadvector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t1 = -t0;
        t1
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (9 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Quadvector<(), T, O> {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t1 = x[4] * t0;
        let t2 = x[4] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = x[4] * t4;
        let t10 = -t5;
        let t11 = -t6;
        let t12 = -t7;
        let t13 = -t8;
        let t14 = -t9;
        Quadvector::from_coeffs([t10, t11, t12, t13, t14])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 5` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Quadvector<(), T, O>> {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t4 = x[3] * x[3];
        let t5 = t0 * t0;
        let t6 = x[0].mul_add(x[0], t0);
        let t7 = x[1].mul_add(x[1], t6);
        let t8 = x[2].mul_add(x[2], t4);
        let t9 = t7 + t8;
        let t10 = -t0;
        let (size, d) = (t9, t5);
        let parts = t10 * t10;
        let tol = T::from_i64(5) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[4] * x[4];
        let p1 = -p0;
        let s0 = (p1).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Quadvector::from_coeffs([t0, t1, t2, t3, t4]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Quadvector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[4] * x[4];
        let t2 = t0.mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t3 = x[0] * t2;
        let t4 = x[1] * t2;
        let t5 = x[2] * t2;
        let t6 = x[3] * t2;
        let t7 = x[4] * t2;
        let t8 = t3 * T::from_ratio(3, 2);
        let t9 = t4 * T::from_ratio(3, 2);
        let t10 = t5 * T::from_ratio(3, 2);
        let t11 = t6 * T::from_ratio(3, 2);
        let t12 = t7 * T::from_ratio(3, 2);
        Quadvector::from_coeffs([t8, t9, t10, t11, t12])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

