impl<T: gx::Real, O: gx::Orientation> Multivector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[2] * x[2];
        let t3 = x[4] * x[4];
        let t6 = x[11] * x[11];
        let t8 = x[13] * x[13];
        let t10 = x[15] * x[15];
        let t11 = x[22] * x[22];
        let t13 = x[24] * x[24];
        let t15 = x[30] * x[30];
        let t16 = x[0].mul_add(x[0], t1);
        let t17 = x[3].mul_add(x[3], t3);
        let t18 = t16 + t17;
        let t19 = x[10].mul_add(x[10], t6);
        let t20 = x[12].mul_add(x[12], t11);
        let t21 = t19 + t20;
        let t22 = t18 + t21;
        let t23 = x[5].mul_add(x[5], t8);
        let t24 = x[14].mul_add(x[14], t10);
        let t25 = t23 + t24;
        let t26 = x[23].mul_add(x[23], t13);
        let t27 = x[25].mul_add(x[25], t15);
        let t28 = t26 + t27;
        let t29 = t25 + t28;
        let t30 = t22 - t29;
        t30
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, by Shirokov's method in `Multivector` (no closed form
    /// for `Multivector` here): the inverse as a polynomial of degree 3 whose coefficients come
    /// from the scalar parts of powers (the FaddeevâLeVerrier recursion on left multiplication,
    /// 3 products in `Multivector`), on the part of `x` free of the null direction(s), then a finite series for the
    /// nilpotent rest (1 term(s)), then 1 NewtonâSchulz step(s) (docs/design.md, ADR-037). `x` is scaled to its largest
    /// coefficient first. Not finite where `x` has no inverse.
    #[inline]
    pub fn inverse(self) -> Multivector<(), T, O>
    where
        T: gx::Real,
    {
        T::vectorize(#[inline(always)] move || {
        let mut size = T::zero();
        for c in self.c {
            size = size.max(c.abs());
        }
        let scale = size.recip();
        let mut x = Multivector::<(), T>::zero();
        x.c[0] = self.c[0] * scale;
        x.c[1] = self.c[1] * scale;
        x.c[2] = self.c[2] * scale;
        x.c[3] = self.c[3] * scale;
        x.c[4] = self.c[4] * scale;
        x.c[5] = self.c[5] * scale;
        x.c[6] = self.c[6] * scale;
        x.c[7] = self.c[7] * scale;
        x.c[8] = self.c[8] * scale;
        x.c[9] = self.c[9] * scale;
        x.c[10] = self.c[10] * scale;
        x.c[11] = self.c[11] * scale;
        x.c[12] = self.c[12] * scale;
        x.c[13] = self.c[13] * scale;
        x.c[14] = self.c[14] * scale;
        x.c[15] = self.c[15] * scale;
        x.c[16] = self.c[16] * scale;
        x.c[17] = self.c[17] * scale;
        x.c[18] = self.c[18] * scale;
        x.c[19] = self.c[19] * scale;
        x.c[20] = self.c[20] * scale;
        x.c[21] = self.c[21] * scale;
        x.c[22] = self.c[22] * scale;
        x.c[23] = self.c[23] * scale;
        x.c[24] = self.c[24] * scale;
        x.c[25] = self.c[25] * scale;
        x.c[26] = self.c[26] * scale;
        x.c[27] = self.c[27] * scale;
        x.c[28] = self.c[28] * scale;
        x.c[29] = self.c[29] * scale;
        x.c[30] = self.c[30] * scale;
        x.c[31] = self.c[31] * scale;
        // The body `a` (no null direction) and the nilpotent rest `n = x â a`.
        let mut a = x;
        a.c[1] = T::zero(); a.c[6] = T::zero(); a.c[7] = T::zero(); a.c[8] = T::zero(); a.c[9] = T::zero(); a.c[16] = T::zero(); a.c[17] = T::zero(); a.c[18] = T::zero(); a.c[19] = T::zero(); a.c[20] = T::zero(); a.c[21] = T::zero(); a.c[26] = T::zero(); a.c[27] = T::zero(); a.c[28] = T::zero(); a.c[29] = T::zero(); a.c[31] = T::zero();
        let n = x - a;
        // Uâ = a, Câ = (N/k) â¨Uââ©â, Uâââ = a (Uâ â Câ); then aâ»Â¹ = (U_{Nâ1} â C_{Nâ1}) / C_N.
        let mut prev = a;
        let c = a.c[0] * T::from_i64(4);
        prev.c[0] = prev.c[0] - c;
        for k in 2..4i64 {
            let u = a * prev;
            let c = u.c[0] * T::from_ratio(4, k);
            prev = u;
            prev.c[0] = prev.c[0] - c;
        }
        let det = (a * prev).c[0];
        let mut y = prev.gp(det.recip());
        // xâ»Â¹ = Î£â (âaâ»Â¹ n)áµ aâ»Â¹, k = 0..=1: (aâ»Â¹ n)^2 = 0, every term holding a null
        // direction twice.
        let m = -(y * n);
        let mut term = y;
        for _ in 0..1 {
            term = m * term;
            y = y + term;
        }
        // NewtonâSchulz, y â y (2 â x y), squares the residual: the recursion loses digits as
        // its degree grows (to 10â»â´ at degree 32), and the step(s) restore them.
        for _ in 0..1 {
            let mut t = -(x * y);
            t.c[0] = t.c[0] + T::from_i64(2);
            y = y * t;
        }
        y.gp(scale).with_orientation()
        })
    }

    /// [`inverse`](Self::inverse), or `None` where it fails: where a coefficient of the
    /// residual `x xâ»Â¹ â 1` is above `âÎµ`, in any lane, or the inverse is not finite. (The
    /// general inverse has no Study number `x ~x` to test against `âxâÂ²`, as the closed forms'
    /// `try_inverse` does; the residual is the test of the iterative solvers.)
    #[inline]
    pub fn try_inverse(self) -> Option<Multivector<(), T, O>> {
        let y = self.inverse();
        let mut x = Multivector::<(), T>::zero();
        x.c[0] = self.c[0];
        x.c[1] = self.c[1];
        x.c[2] = self.c[2];
        x.c[3] = self.c[3];
        x.c[4] = self.c[4];
        x.c[5] = self.c[5];
        x.c[6] = self.c[6];
        x.c[7] = self.c[7];
        x.c[8] = self.c[8];
        x.c[9] = self.c[9];
        x.c[10] = self.c[10];
        x.c[11] = self.c[11];
        x.c[12] = self.c[12];
        x.c[13] = self.c[13];
        x.c[14] = self.c[14];
        x.c[15] = self.c[15];
        x.c[16] = self.c[16];
        x.c[17] = self.c[17];
        x.c[18] = self.c[18];
        x.c[19] = self.c[19];
        x.c[20] = self.c[20];
        x.c[21] = self.c[21];
        x.c[22] = self.c[22];
        x.c[23] = self.c[23];
        x.c[24] = self.c[24];
        x.c[25] = self.c[25];
        x.c[26] = self.c[26];
        x.c[27] = self.c[27];
        x.c[28] = self.c[28];
        x.c[29] = self.c[29];
        x.c[30] = self.c[30];
        x.c[31] = self.c[31];
        let y0: Multivector<(), T> = y.with_orientation();
        let mut r = (x * y0).c;
        r[0] = r[0] - T::one();
        let tol = T::epsilon().sqrt();
        if r.iter().all(|&c| T::all_lt(c.abs(), tol)) {
            Some(y).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

}

impl<T: gx::Real, O: gx::Orientation> gx::Inverse for Multivector<(), T, O> {
    type Output = Multivector<(), T, O>;
    #[inline(always)]
    fn inverse(self) -> Self::Output {
        Self::inverse(self)
    }
    #[inline(always)]
    fn try_inverse(self) -> Option<Self::Output> {
        Self::try_inverse(self)
    }
}

impl<T: gx::Real, O: gx::Orientation> gx::Norm for Multivector<(), T, O> {
    #[inline(always)]
    fn norm_squared(self) -> T {
        Self::norm_squared(self)
    }
    #[inline(always)]
    fn norm(self) -> T {
        Self::norm(self)
    }
}

